  margin-inline: auto;
}

.skip-link {
  position: absolute;
  left: var(--space-2);
  top: -10rem;
  z-index: 10;
  padding: 0.75rem 1rem;
  background: var(--on-glaze);
  color: var(--ink);
  font-weight: 700;
}
.skip-link:focus { top: var(--space-2); }

/* ---------- The dip line ---------- */

/* An element with .dipped gets a glaze drip hanging off its bottom edge.
   Set --dip-color to the glaze that is dripping. */
.dipped { position: relative; }
.dipped::after,
.hero::after,
.footer::before,
.photo-frame::before,
.tile::before {
  content: "";
  position: absolute;
  pointer-events: none;
  -webkit-mask: var(--drip) repeat-x bottom / 15rem 100%;
  mask: var(--drip) repeat-x bottom / 15rem 100%;
}

/* ---------- Buttons & links ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.6rem 1.25rem;
  border-radius: 999px 999px 999px 999px / 60% 60% 40% 40%;
  background: var(--glaze);
  color: var(--on-glaze);
  font-weight: 700;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 180ms var(--ease-out), transform 100ms var(--ease-out);
}
.btn:active { background: var(--glaze-deep); transform: translateY(1px); }
.btn-light { background: var(--on-glaze); color: var(--glaze); }
.btn-light:active { background: var(--clay); color: var(--ink); }

@media (hover: hover) {
  .btn:hover { background: var(--glaze-deep); }
  .btn-light:hover { background: var(--clay); color: var(--ink); }
  .text-link:hover, .nav-links a:hover { text-decoration-thickness: 2px; }
}

/* ---------- Hero (cobalt glaze) ---------- */

.hero {
  --ring: oklch(0.90 0.11 95);
  position: relative;
  z-index: 1;
  background: var(--glaze);
  color: var(--on-glaze);
  padding-bottom: var(--space-5);
