    radial-gradient(circle at 70% 75%, oklch(0.45 0.05 50 / 0.2) 0 1.2px, transparent 1.7px);
  background-size: 23px 19px, 31px 37px;
  color: var(--ink);
  padding-top: calc(var(--space-5) + var(--drip-h));
}
