  inset: 0 0 auto 0;
  height: var(--drip-h);
  background: var(--bg);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: var(--space-4);
}
.footer h2 { margin-bottom: var(--space-2); }
.footer h3 { font-size: 1.25rem; margin-bottom: var(--space-1); margin-top: 0.6rem; }
address { font-style: normal; font-size: 1.25rem; line-height: 1.5; }
.footer a { display: inline-block; padding-block: 0.25rem; }
.footer-base { padding-block: var(--space-5) var(--space-3); font-size: 1rem; }

/* ---------- Entrance: the glaze settles ---------- */

@media (prefers-reduced-motion: no-preference) {
  .hero-copy > * { animation: rise 700ms var(--ease-out) both; }
  .hero-copy > :nth-child(2) { animation-delay: 90ms; }
  .hero-copy > :nth-child(3) { animation-delay: 180ms; }
  .hero::after { animation: pour 900ms var(--ease-out) 150ms both; }
}
@keyframes rise { from { opacity: 0; transform: translateY(0.75rem); } }
@keyframes pour { from { transform: scaleY(0.35); } }

/* ---------- Responsive ---------- */

@media (max-width: 52em) {
  .hero-body { grid-template-columns: minmax(0, 1fr); padding-top: var(--space-4); }
  .photo-hero .photo-frame { aspect-ratio: 4 / 3; }
