  .workshop { grid-template-columns: 3.5rem minmax(0, 1fr); }
  .tile { width: 3.5rem; }
  .tile::before { -webkit-mask-size: 3.5rem 100%; mask-size: 3.5rem 100%; }
  .workshop-buy {
    grid-column: 2;
    grid-template-columns: auto auto;
    justify-content: space-between;
    align-items: center;
    justify-items: start;
    text-align: left;
  }
  .price { align-items: flex-start; }
  .studio { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "copy copy" "wide wide" "a b"; }
  .photo-b { margin-top: 0; }
  .footer-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .footer-grid > :first-child { grid-column: 1 / -1; }
}

@media (max-width: 40em) {
  .nav-book { display: none; }
  .workshop { grid-template-columns: minmax(0, 1fr); }
  .tile { width: 3rem; }
  .workshop-buy { grid-column: 1; }
  .studio { grid-template-columns: minmax(0, 1fr); grid-template-areas: "copy" "wide" "a" "b"; }
  .footer-grid { grid-template-columns: minmax(0, 1fr); }
}

@media (pointer: coarse) {
  .btn { padding-inline: 1.5rem; }
}

