  font-size: 2.4rem;
  line-height: 1;
  font-variant-numeric: tabular-nums lining-nums;
}
.per { font-size: 1rem; color: var(--muted); }

.booking-note { margin-top: var(--space-3); color: var(--muted); }
.booking-note a { color: var(--ink); }

/* ---------- Studio ---------- */

.studio {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1fr);
  grid-template-areas:
    "copy wide wide"
    "a    b    .";
  gap: var(--space-4) var(--space-3);
  padding-block: var(--space-6) calc(var(--space-6) + var(--drip-h));
}
.studio-copy { grid-area: copy; align-self: center; }
.studio-copy p { margin-top: var(--space-2); }
.studio-copy p + p { color: var(--muted); }
.photo-wide { grid-area: wide; }
.photo-a { grid-area: a; }
.photo-b { grid-area: b; margin-top: var(--space-5); }
.photo-wide .photo-frame { aspect-ratio: 16 / 10; }

/* ---------- Footer (the unglazed foot) ---------- */

.footer {
  --ring: var(--glaze);
  position: relative;
  background-color: var(--clay);
  background-image:
    radial-gradient(circle at 30% 40%, oklch(0.45 0.05 50 / 0.3) 0 1px, transparent 1.5px),
    radial-gradient(circle at 70% 75%, oklch(0.45 0.05 50 / 0.2) 0 1.2px, transparent 1.7px);
  background-size: 23px 19px, 31px 37px;
  color: var(--ink);
  padding-top: calc(var(--space-5) + var(--drip-h));
}
.footer::before {
  inset: 0 0 auto 0;
  height: var(--drip-h);
  background: var(--bg);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: var(--space-4);
}
.footer h2 { margin-bottom: var(--space-2); }
.footer h3 { font-size: 1.25rem; margin-bottom: var(--space-1); margin-top: 0.6rem; }
address { font-style: normal; font-size: 1.25rem; line-height: 1.5; }
.footer a { display: inline-block; padding-block: 0.25rem; }
.footer-base { padding-block: var(--space-5) var(--space-3); font-size: 1rem; }

/* ---------- Entrance: the glaze settles ---------- */

@media (prefers-reduced-motion: no-preference) {
  .hero-copy > * { animation: rise 700ms var(--ease-out) both; }
  .hero-copy > :nth-child(2) { animation-delay: 90ms; }
  .hero-copy > :nth-child(3) { animation-delay: 180ms; }
  .hero::after { animation: pour 900ms var(--ease-out) 150ms both; }
}
@keyframes rise { from { opacity: 0; transform: translateY(0.75rem); } }
@keyframes pour { from { transform: scaleY(0.35); } }

/* ---------- Responsive ---------- */

@media (max-width: 52em) {
  .hero-body { grid-template-columns: minmax(0, 1fr); padding-top: var(--space-4); }
  .photo-hero .photo-frame { aspect-ratio: 4 / 3; }
  .section-head { grid-template-columns: minmax(0, 1fr); }
  .workshop { grid-template-columns: 3.5rem minmax(0, 1fr); }
  .tile { width: 3.5rem; }
  .tile::before { -webkit-mask-size: 3.5rem 100%; mask-size: 3.5rem 100%; }
  .workshop-buy {
    grid-column: 2;
    grid-template-columns: auto auto;
    justify-content: space-between;
    align-items: center;
    justify-items: start;
    text-align: left;
  }
  .price { align-items: flex-start; }
  .studio { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "copy copy" "wide wide" "a b"; }
  .photo-b { margin-top: 0; }
  .footer-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .footer-grid > :first-child { grid-column: 1 / -1; }
}

@media (max-width: 40em) {
  .nav-book { display: none; }
  .workshop { grid-template-columns: minmax(0, 1fr); }
  .tile { width: 3rem; }
  .workshop-buy { grid-column: 1; }
  .studio { grid-template-columns: minmax(0, 1fr); grid-template-areas: "copy" "wide" "a" "b"; }
  .footer-grid { grid-template-columns: minmax(0, 1fr); }
}

@media (pointer: coarse) {
  .btn { padding-inline: 1.5rem; }
}

@media (prefers-contrast: more) {
  .lede, .section-head p, .per, .when, figcaption, .booking-note { color: inherit; }
  .hero .lede { color: var(--on-glaze); }
